import { ChangeDetectionStrategy, Component, computed, input, model, output } from '@angular/core';
import { VcrAbstractClauseCardComponent, AbstractClauseRowRef } from './abstract-clause-card.component';
import { VcrAbstractSummaryHeaderComponent } from './abstract-summary-header.component';
import { AbstractClause, visibleAbstractClauses } from './abstract-summary.model';

/**
 * The abstract summary panel a page places inside one of its own tabs.
 *
 * The header is search, Add Clause, the template name and Export Abstracts. Below it, each
 * abstract clause is a card, each clause detail is a row, and each detail's points are the
 * indented rows under that detail. With no template selected, the cards are replaced by the
 * prompt to choose one.
 *
 * The host supplies the template. Abstract templates are custom-object records; which object
 * those records come from is not chosen here yet.
 */
@Component({
  selector: 'vcr-abstract-summary',
  standalone: true,
  imports: [VcrAbstractSummaryHeaderComponent, VcrAbstractClauseCardComponent],
  templateUrl: './abstract-summary.component.html',
  styleUrl: './abstract-summary.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class VcrAbstractSummaryComponent {
  readonly templateName = input<string | null>(null);
  readonly clauses = input<AbstractClause[]>([]);
  readonly search = model('');

  readonly addClause = output<void>();
  readonly exportAbstracts = output<void>();
  readonly selectTemplate = output<void>();
  readonly addDataPoint = output<string>();
  readonly editRow = output<AbstractClauseRowRef>();
  readonly copyRow = output<AbstractClauseRowRef>();

  readonly visibleClauses = computed(() => visibleAbstractClauses(this.clauses(), this.search()));

  hasTemplate(): boolean {
    const name = this.templateName();
    return name !== null && name.trim() !== '';
  }
}
