import { ChangeDetectionStrategy, Component, input, output, signal } from '@angular/core';
import { AbstractClause, AbstractClauseDetail, AbstractClauseDetailPoint } from './abstract-summary.model';

/** Which row an edit or copy action belongs to. */
export interface AbstractClauseRowRef {
  clauseId: string;
  detailId: string;
  pointId: string | null;
}

/**
 * One abstract clause, drawn as a card.
 *
 * The heading is the clause. Each detail is a row, and that detail's points are the indented
 * rows beneath it. The chevron folds the rows away; they start open.
 */
@Component({
  selector: 'vcr-abstract-clause-card',
  standalone: true,
  templateUrl: './abstract-clause-card.component.html',
  styleUrl: './abstract-clause-card.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class VcrAbstractClauseCardComponent {
  readonly clause = input.required<AbstractClause>();

  readonly addDataPoint = output<string>();
  readonly editRow = output<AbstractClauseRowRef>();
  readonly copyRow = output<AbstractClauseRowRef>();

  readonly expanded = signal(true);

  toggle(): void {
    this.expanded.update((open) => !open);
  }

  detailRef(detail: AbstractClauseDetail): AbstractClauseRowRef {
    return { clauseId: this.clause().id, detailId: detail.id, pointId: null };
  }

  pointRef(detail: AbstractClauseDetail, point: AbstractClauseDetailPoint): AbstractClauseRowRef {
    return { clauseId: this.clause().id, detailId: detail.id, pointId: point.id };
  }
}
