import { ChangeDetectionStrategy, Component, input, model, output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { ButtonModule } from 'primeng/button';
import { IconField } from 'primeng/iconfield';
import { InputIcon } from 'primeng/inputicon';
import { InputText } from 'primeng/inputtext';

/**
 * The toolbar above an abstract summary's clause cards.
 *
 * Search on the left, then Add Clause. On the right, the selected template's name and Export
 * Abstracts. No template name draws "No Template Selected" in place of the name pill. This is the
 * bar inside the summary, not the page tabs around it.
 */
@Component({
  selector: 'vcr-abstract-summary-header',
  standalone: true,
  imports: [FormsModule, ButtonModule, IconField, InputIcon, InputText],
  templateUrl: './abstract-summary-header.component.html',
  styleUrl: './abstract-summary-header.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class VcrAbstractSummaryHeaderComponent {
  /** Two-way, so the summary can filter its cards from the same value the input shows. */
  readonly search = model('');
  /** Null when the reader has not chosen a template yet. */
  readonly templateName = input<string | null>(null);

  readonly addClause = output<void>();
  readonly exportAbstracts = output<void>();
  readonly selectTemplate = output<void>();
}
